const fs=require("fs"),path=require("path"),crypto=require("crypto"),mime=require("mime-types"),Helpers={sanitizeFilename(filename){if(!filename)return"unnamed_file";let safe=path.basename(filename);return safe=safe.replace(/[/\\?%*:|"<>]/g,"_"),safe=safe.replace(/^\.+/,""),safe.trim()||"unnamed_file"},generateId(prefix="item"){const rand=crypto.randomBytes(8).toString("hex");return`${prefix}_${Date.now().toString(36)}_${rand}`},formatBytes(bytes,decimals=2){if(!bytes||0===bytes)return"0 B";const dm=decimals<0?0:decimals,i=Math.floor(Math.log(bytes)/Math.log(1024));return parseFloat((bytes/Math.pow(1024,i)).toFixed(dm))+" "+["B","KB","MB","GB","TB","PB"][i]},getMimeType(filename){const ext=path.extname(filename).toLowerCase().replace(".",""),customMap={wpress:"application/octet-stream",mkv:"video/webm",apk:"application/vnd.android.package-archive",ipa:"application/octet-stream"};return customMap[ext]?customMap[ext]:mime.lookup(filename)||"application/octet-stream"},success:(res,data={},message="Success",statusCode=200)=>res.status(statusCode).json({success:!0,status:"success",message:message,...data,data:data}),error:(res,message="Internal Server Error",statusCode=500)=>res.status(statusCode).json({success:!1,status:"error",message:message,error:message}),removeDir(dirPath){if(fs.existsSync(dirPath))try{fs.rmSync(dirPath,{recursive:!0,force:!0})}catch(err){console.error(`Error removing dir ${dirPath}:`,err.message)}},cleanStaleUploadSessions(tempDir,maxAgeSecs=3600){if(!fs.existsSync(tempDir))return;const now=Date.now();try{const entries=fs.readdirSync(tempDir);for(const entry of entries){const fullPath=path.join(tempDir,entry);try{const stats=fs.statSync(fullPath);if(stats.isDirectory()){(now-stats.mtimeMs)/1e3>maxAgeSecs&&Helpers.removeDir(fullPath)}}catch(e){}}}catch(e){console.error("Error cleaning stale upload sessions:",e.message)}}};module.exports=Helpers;